-- SHCO Full OEs - Auto-generated from NABH SHCO Standards 3rd Edition
-- Total: 408 Objective Elements across 10 chapters

-- 1. OE reference table
create table if not exists public.shco_full_oes (
  id uuid default gen_random_uuid() primary key,
  chapter text not null,
  chapter_name text not null,
  standard_code text not null,
  standard_text text not null,
  oe_code text unique not null,
  level text not null check (level in ('Core','Commitment','Achievement','Excellence')),
  text text not null
);

-- 2. Scores table
create table if not exists public.shco_full_scores (
  id uuid default gen_random_uuid() primary key,
  hospital_id uuid references public.hospitals(id) on delete cascade,
  oe_code text references public.shco_full_oes(oe_code),
  score int check (score between 1 and 5),
  scored_at timestamptz default now(),
  unique(hospital_id, oe_code)
);

-- 3. RLS on shco_full_oes (reference table - read by any authenticated user)
alter table public.shco_full_oes enable row level security;
drop policy if exists "shco_full_oes_read" on public.shco_full_oes;
create policy "shco_full_oes_read" on public.shco_full_oes
  for select to authenticated using (true);

-- 4. RLS on shco_full_scores (hospital-scoped - matches elc_scores pattern)
alter table public.shco_full_scores enable row level security;
drop policy if exists "shco_full_scores_member_all" on public.shco_full_scores;
create policy "shco_full_scores_member_all" on public.shco_full_scores
  for all to authenticated
  using (hospital_id in (select hospital_id from public.profiles where id = auth.uid()))
  with check (hospital_id in (select hospital_id from public.profiles where id = auth.uid()));

