insert into public.shco_full_oes (chapter, chapter_name, standard_code, standard_text, oe_code, level, text) values
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.1', 'The organization defines and displays the healthcare services that it provides.', 'AAC.1.a', 'Commitment', 'The healthcare services being provided are defined and are in consonance with the needs of the community.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.1', 'The organization defines and displays the healthcare services that it provides.', 'AAC.1.b', 'Commitment', 'Each defined healthcare service should have diagnostic and treatment services with suitably qualified personnel who provide out-patient, in-patient and emergency cover.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.1', 'The organization defines and displays the healthcare services that it provides.', 'AAC.1.c', 'Commitment', 'Scope of healthcare services of each department is defined.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.1', 'The organization defines and displays the healthcare services that it provides.', 'AAC.1.d', 'Commitment', 'The organization''s defined healthcare services are prominently displayed.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.a', 'Commitment', 'The organization has a mechanism for registering and admitting patients'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.b', 'Core', 'Aunique identification number is generated at the end of registration.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.c', 'Commitment', 'Patients are accepted only if the organization can provide the required service'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.d', 'Commitment', 'The organization has a mechanism to address management of patients during non-availability of beds.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.e', 'Achievement', 'Access to the healthcare services in the organization is prioritized according to the clinical needs of the patient.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.2', 'The organization has a well-defined registration, admission and transfer process.', 'AAC.2.f', 'Commitment', 'Transfer–in and transfer-out / referral of patients to the organization is done appropriately.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.3', 'Patients cared for by the organization undergo an established initial assessment and regular re-assessment', 'AAC.3.a', 'Core', 'The initial assessment for the out–patients, day-care, in-patients and emergency patients is done.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.3', 'Patients cared for by the organization undergo an established initial assessment and regular re-assessment', 'AAC.3.b', 'Achievement', 'The initial assessment results in a documented care plan.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.3', 'Patients cared for by the organization undergo an established initial assessment and regular re-assessment', 'AAC.3.c', 'Core', 'Patients are reassessed at appropriate intervals to determine their response to treatment and to plan further treatment or discharge.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.3', 'Patients cared for by the organization undergo an established initial assessment and regular re-assessment', 'AAC.3.d', 'Commitment', 'Out-patients are informed of their next follow-up, where appropriate.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.3', 'Patients cared for by the organization undergo an established initial assessment and regular re-assessment', 'AAC.3.e', 'Commitment', 'The organization lays down guidelines and implements processes to identify early warning signs of change or deterioration in clinical conditions for initiating prompt intervention.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.a', 'Commitment', 'Scope of the laboratory services is commensurate to the services provided by the organization.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.b', 'Commitment', 'The infrastructure (physical and equipment) and human resources are adequate to provide the defined scope of services'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.c', 'Commitment', 'Requisition for tests, collection, identification, handling, safe transportation, processing and disposal of specimens is performed according to written guidance.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.d', 'Commitment', 'Laboratory results are available within a defined time frame.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.e', 'Commitment', 'Critical results are intimated to the person concerned at the earliest.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.f', 'Commitment', 'Laboratory tests not available in the organization are outsourced to organization(s) based on their quality assurance system.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.g', 'Commitment', 'The laboratory quality assurance programme is implemented.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.4', 'Laboratory services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.4.h', 'Commitment', 'The programme includes periodic calibration and maintenance of all equipment.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.a', 'Core', 'Imaging services comply with legal and other requirements.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.b', 'Commitment', 'Scope of the imaging services is commensurate to the services provided by the organization.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.c', 'Commitment', 'The infrastructure (physical and equipment) and human resources are adequate to provide for its defined scope of services.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.d', 'Commitment', 'Imaging results are available in the standardised manner within a defined time frame'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.e', 'Commitment', 'Critical results are intimated immediately to the personnel concerned.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.f', 'Commitment', 'Imaging tests not available in the organization are outsourced to organization(s) based on their quality assurance system.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.g', 'Commitment', 'The quality assurance programme for imaging services is implemented.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.h', 'Achievement', 'The programme addresses periodic internal / external peer review of imaging protocols and results using appropriate sampling.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.5', 'Imaging services are provided as per the scope of services of the organization and adhere to best practices.', 'AAC.5.i', 'Commitment', 'The programme includes periodic calibration and maintenance of all equipment.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.6', 'There is an established safety programme in the laboratory and imaging services', 'AAC.6.a', 'Commitment', 'The laboratory-safety programme is implemented.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.6', 'There is an established safety programme in the laboratory and imaging services', 'AAC.6.b', 'Commitment', 'Laboratory personnel are appropriately trained in safe practices and are provided with appropriate safety measures.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.6', 'There is an established safety programme in the laboratory and imaging services', 'AAC.6.c', 'Commitment', 'Patients are appropriately screened for safety / risk before imaging.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.6', 'There is an established safety programme in the laboratory and imaging services', 'AAC.6.d', 'Commitment', 'Imaging personnel and patients use appropriate radiation safety and monitoring devices where applicable, and are trained in imaging safety practices and radiation-safety measures.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.6', 'There is an established safety programme in the laboratory and imaging services', 'AAC.6.e', 'Commitment', 'Imaging signage is prominently displayed in all appropriate locations.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.7', 'Patient care is continuous and multidisciplinary in nature.', 'AAC.7.a', 'Commitment', 'During all phases of care, there is a qualified individual identified as responsible for the patient''s care.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.7', 'Patient care is continuous and multidisciplinary in nature.', 'AAC.7.b', 'Commitment', 'Information about the patient''s care and response to treatment is shared among medical, nursing and other care-providers, including referrals to other departments.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.7', 'Patient care is continuous and multidisciplinary in nature.', 'AAC.7.c', 'Core', 'The organization implements standardised hand-over communication during each staffing shift, between shifts and during transfers between units/ departments.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.7', 'Patient care is continuous and multidisciplinary in nature.', 'AAC.7.d', 'Commitment', 'Patient transfer within the organization is done safely.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.a', 'Commitment', 'Adischarge summary is given to all the patients leaving the organization (including patients leaving against medical advice).'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.b', 'Commitment', 'Discharge summary contains the patient''s name, unique identification number, date of admission and date of discharge.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.c', 'Commitment', 'Discharge summary contains the reasons for admission, significant findings and diagnosis, the patient''s condition at the time of discharge, information regarding investigation results, any procedure performed, medication administered and other treatment given.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.d', 'Commitment', 'Discharge summary contains follow-up advice, medication and other instructions in an understandable manner.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.e', 'Achievement', 'Discharge summary incorporates instructions about when and how to obtain urgent care.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.f', 'Commitment', 'In case of death, the summary of the case also includes the cause of death.'),
('AAC', 'Access, Assessment and Continuity of Care', 'AAC.8', 'The organization has an established discharge process, and defines the content of the discharge summary.', 'AAC.8.g', 'Excellence', 'The organisation adheres to planned discharge and identify special needs regarding care following discharge.'),
('COP', 'Care of Patients', 'COP.1', 'Uniform care to patients is provided in all settings of the organization and is guided by written guidance, and the applicable laws and regulations', 'COP.1.a', 'Core', 'The organization has a uniform process for identification of patients and at a minimum, uses two identifiers.'),
('COP', 'Care of Patients', 'COP.1', 'Uniform care to patients is provided in all settings of the organization and is guided by written guidance, and the applicable laws and regulations', 'COP.1.b', 'Commitment', 'Care shall be provided in consonance with applicable laws and regulations.'),
('COP', 'Care of Patients', 'COP.1', 'Uniform care to patients is provided in all settings of the organization and is guided by written guidance, and the applicable laws and regulations', 'COP.1.c', 'Achievement', 'The organization adopts evidence-based clinical practice guidelines and/or clinical protocols to guide uniform patient care.'),
('COP', 'Care of Patients', 'COP.1', 'Uniform care to patients is provided in all settings of the organization and is guided by written guidance, and the applicable laws and regulations', 'COP.1.d', 'Commitment', 'Care delivery is uniform for a given clinical condition when similar care is provided in more than one setting.'),
('COP', 'Care of Patients', 'COP.1', 'Uniform care to patients is provided in all settings of the organization and is guided by written guidance, and the applicable laws and regulations', 'COP.1.e', 'Excellence', 'Telemedicine facility is provided safely and securely based on written guidance.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.a', 'Commitment', 'There shall be an identified area in the organization, which is easily accessible to receive and manage emergency patients, with adequate and appropriate resources.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.b', 'Core', 'The organization manages medico-legal cases and provides emergency care in consonance with statutory requirements and in accordance with written guidance.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.c', 'Commitment', 'Initiation of appropriate care is guided by a system of triage.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.d', 'Commitment', 'Patients waiting in the emergency are reassessed as appropriate for the change in status.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.e', 'Commitment', 'Admission, discharge to home or transfer to another organization is documented, and a discharge note shall be given to the patient.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.f', 'Achievement', 'The organization shall implement a quality assurance programme.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.g', 'Commitment', 'The organization has systems in place for the management of patients found dead on arrival and patients who die within a few minutes of arrival.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.h', 'Commitment', 'The organization has access to ambulance services commensurate with the scope of services provided by it.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.i', 'Commitment', 'The ambulance(s) is fit for purpose, is operated by trained personnel, is appropriately equipped, and ensures that emergency medications are available in the ambulance.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.j', 'Excellence', 'The emergency department identifies opportunities to initiate treatment at the earliest, when the patient is in transit to the organization.'),
('COP', 'Care of Patients', 'COP.2', 'Emergency services including ambulance, and management of disasters, are provided in accordance with written guidance, applicable laws and regulations.', 'COP.2.k', 'Commitment', 'The organization manages potential community emergencies, epidemics and other disasters as per a documented plan.'),
('COP', 'Care of Patients', 'COP.3', 'Cardio-pulmonary resuscitation services are provided uniformly across the organization.', 'COP.3.a', 'Commitment', 'Resuscitation services are available to patients at all times.'),
('COP', 'Care of Patients', 'COP.3', 'Cardio-pulmonary resuscitation services are provided uniformly across the organization.', 'COP.3.b', 'Commitment', 'During cardiopulmonary resuscitation, assigned roles and responsibilities are complied with, and the events during cardiopulmonary resuscitation are recorded.'),
('COP', 'Care of Patients', 'COP.3', 'Cardio-pulmonary resuscitation services are provided uniformly across the organization.', 'COP.3.c', 'Commitment', 'The equipment and medications for use during cardiopulmonary resuscitation are available in various areas of the organization.'),
('COP', 'Care of Patients', 'COP.3', 'Cardio-pulmonary resuscitation services are provided uniformly across the organization.', 'COP.3.d', 'Commitment', 'Amultidisciplinary committee does a post-event analysis of all cardiopulmonary resuscitations, and corrective and preventive measures are taken based on this.'),
('COP', 'Care of Patients', 'COP.4', 'Nursing care is provided to patients in the organization in consonance with clinical protocols.', 'COP.4.a', 'Core', 'Nursing care is aligned and integrated with overall patient care, and is documented in the patient record*.'),
('COP', 'Care of Patients', 'COP.4', 'Nursing care is provided to patients in the organization in consonance with clinical protocols.', 'COP.4.b', 'Commitment', 'Assignment of patient care is done as per current good clinical / nursing practice guidelines.'),
('COP', 'Care of Patients', 'COP.4', 'Nursing care is provided to patients in the organization in consonance with clinical protocols.', 'COP.4.c', 'Commitment', 'Nurses are provided with appropriate and adequate equipment for providing safe and efficient nursing services.'),
('COP', 'Care of Patients', 'COP.4', 'Nursing care is provided to patients in the organization in consonance with clinical protocols.', 'COP.4.d', 'Excellence', 'The organization develops and implements nursing clinical practice guidelines reflecting current standards of practice*.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.a', 'Commitment', 'Transfusion services are commensurate with the services provided by the organization, and are governed by the applicable laws and regulations.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.b', 'Core', 'Transfusion of blood and blood components is done safely.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.c', 'Commitment', 'Blood and blood components are used rationally*.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.d', 'Commitment', 'Informed consent is obtained for transfusion of blood and blood products, and for donation.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.e', 'Commitment', 'Blood/blood components are available for use in emergency situations within a defined time frame.'),
('COP', 'Care of Patients', 'COP.5', 'Transfusion services are provided as per the scope of services of the organization, safely.', 'COP.5.f', 'Achievement', 'Post-transfusion form is collected, reactions if any identified and are analysed for corrective and preventive actions.'),
