('COP', 'Care of Patients', 'COP.7', 'Organization provides safe obstetric care.', 'COP.7.e', 'Commitment', 'The organization caring for high risk obstetric cases has the human resources and facilities to take care of neonates of such cases.'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.a', 'Commitment', 'Paediatric services are organised and provided safely.'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.b', 'Commitment', 'Neonatal care is in consonance with the national/ international guidelines'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.c', 'Commitment', 'Those who care for children have age-specific competency.'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.d', 'Commitment', 'Provisions are made for special care of children.'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.e', 'Commitment', 'Patient assessment includes nutritional, growth, developmental and immunisation assessment.'),
('COP', 'Care of Patients', 'COP.8', 'Organization provides safe paediatric services.', 'COP.8.f', 'Commitment', 'The organization has measures in place to prevent child/neonate abduction and abuse.'),
('COP', 'Care of Patients', 'COP.9', 'Procedural sedation is provided consistently and safely.', 'COP.9.a', 'Commitment', 'Procedural sedation is administered in a consistent manner.'),
('COP', 'Care of Patients', 'COP.9', 'Procedural sedation is provided consistently and safely.', 'COP.9.b', 'Commitment', 'Informed consent for administration of procedural sedation is obtained.'),
('COP', 'Care of Patients', 'COP.9', 'Procedural sedation is provided consistently and safely.', 'COP.9.c', 'Commitment', 'Competent and trained persons perform and monitor sedation.'),
