('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.a', 'Commitment', 'Anaesthesia services are administered in a consistent and safe manner.'),
('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.b', 'Core', 'The pre-anaesthesia assessment results in the formulation of an anaesthesia plan which is documented*.'),
('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.c', 'Commitment', 'Apre-induction assessment is performed and documented.'),
('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.d', 'Commitment', 'Informed consent for administration of anaesthesia, is obtained.'),
('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.e', 'Core', 'Patients are monitored while under anaesthesia*.'),
('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.f', 'Commitment', 'Post anaesthesia monitoring is documented, and patients are discharged from the recovery area based on objective criteria*.'),
