('COP', 'Care of Patients', 'COP.10', 'Anaesthesia services are provided consistently and safely.', 'COP.10.h', 'Achievement', 'Intra-operative adverse anaesthesia events are recorded and monitored.'),
('COP', 'Care of Patients', 'COP.11', 'Clinical procedures, as well as procedures in the operation theatre are performed in a safe and consistent manner.', 'COP.11.a', 'Commitment', 'Clinical procedures as well as procedures done in operation theatres are done in a consistent and safe manner.'),
('COP', 'Care of Patients', 'COP.11', 'Clinical procedures, as well as procedures in the operation theatre are performed in a safe and consistent manner.', 'COP.11.b', 'Commitment', 'Surgical patients have a preoperative assessment, a documented pre-operative diagnosis, and pre-operative instructions provided before surgery and documented.'),
('COP', 'Care of Patients', 'COP.11', 'Clinical procedures, as well as procedures in the operation theatre are performed in a safe and consistent manner.', 'COP.11.c', 'Commitment', 'Informed consent is obtained by the doctor prior to the procedure.'),
