('IMS', 'Information Management System', 'IMS.3', 'The medical record reflects the continuity of care.', 'IMS.3.e', 'Commitment', 'In case of death, the medical record contains a copy of the cause of death certificate.'),
('IMS', 'Information Management System', 'IMS.3', 'The medical record reflects the continuity of care.', 'IMS.3.f', 'Commitment', 'Care providers have access to current and past medical record.'),
('IMS', 'Information Management System', 'IMS.4', 'The organisation maintains confidentiality, integrity and security of records, data and information.', 'IMS.4.a', 'Core', 'The organization maintains the confidentiality of records, data and information.'),
('IMS', 'Information Management System', 'IMS.4', 'The organisation maintains confidentiality, integrity and security of records, data and information.', 'IMS.4.b', 'Core', 'The organization maintains the integrity of records, data and information.'),
('IMS', 'Information Management System', 'IMS.4', 'The organisation maintains confidentiality, integrity and security of records, data and information.', 'IMS.4.c', 'Core', 'The organization maintains the security of records, data and information.'),
('IMS', 'Information Management System', 'IMS.4', 'The organisation maintains confidentiality, integrity and security of records, data and information.', 'IMS.4.d', 'Commitment', 'The organization discloses privileged health information as authorized by patient and/ or as required by law.'),
('IMS', 'Information Management System', 'IMS.4', 'The organisation maintains confidentiality, integrity and security of records, data and information.', 'IMS.4.e', 'Commitment', 'Request for access to information in the medical records by patients/physicians and other public agencies are addressed consistently.'),
('IMS', 'Information Management System', 'IMS.5', 'The organization ensures availability of current and relevant documents, records, data and information and provides for retention of the same.', 'IMS.5.a', 'Core', 'The organization has an effective process for document control.'),
('IMS', 'Information Management System', 'IMS.5', 'The organization ensures availability of current and relevant documents, records, data and information and provides for retention of the same.', 'IMS.5.b', 'Core', 'The organization retains patient''s clinical records, data and information, according to its requirements.'),
('IMS', 'Information Management System', 'IMS.5', 'The organization ensures availability of current and relevant documents, records, data and information and provides for retention of the same.', 'IMS.5.c', 'Commitment', 'The retention process provides expected confidentiality and security.'),
('IMS', 'Information Management System', 'IMS.5', 'The organization ensures availability of current and relevant documents, records, data and information and provides for retention of the same.', 'IMS.5.d', 'Commitment', 'The destruction of medical records, data and information is in accordance with the laid-down policy.'),
('IMS', 'Information Management System', 'IMS.6', 'The organisation regularly carries out a review of medical records.', 'IMS.6.a', 'Core', 'The medical records are reviewed periodically.'),
('IMS', 'Information Management System', 'IMS.6', 'The organisation regularly carries out a review of medical records.', 'IMS.6.b', 'Commitment', 'The review uses a representative sample of both active and discharged patients, based on statistical principles.'),
('IMS', 'Information Management System', 'IMS.6', 'The organisation regularly carries out a review of medical records.', 'IMS.6.c', 'Commitment', 'The review is conducted by identified individuals.'),
('IMS', 'Information Management System', 'IMS.6', 'The organisation regularly carries out a review of medical records.', 'IMS.6.d', 'Commitment', 'The review of records is based on identified parameters'),
('IMS', 'Information Management System', 'IMS.6', 'The organisation regularly carries out a review of medical records.', 'IMS.6.e', 'Commitment', 'Appropriate corrective and preventive measures are undertaken on the deficiencies pointed out in the review.');